function varargout=f90_xfluid01_measurement_compat(helperName,varargin)
%F90_XFLUID01_MEASUREMENT_COMPAT Variable-timebase deadband-pair recovery.
helperName=char(string(helperName));
if helperName~="measure_suite"
    if nargout==0
        f90_xfluid01_measurement_compat_core(helperName,varargin{:});
    else
        [varargout{1:nargout}]=f90_xfluid01_measurement_compat_core(helperName,varargin{:});
    end
    return;
end
assert(nargout<=1,"SimuVerity:f90_xfluid01_measurement_compat:MeasureSuiteOutputs", ...
    "The suite measurement has one output.");
s=f90_xfluid01_measurement_compat_core("measure_suite",varargin{:});
if ~s.deadband_valid
    runs=varargin{1};rows=varargin{2};
    [s.deadband_valid,s.deadband_effect_strength, ...
        s.deadband_opening_difference,s.deadband_flow_difference, ...
        s.deadband_pair_performance_good]=deadband_pair_variable_timebase(runs,rows);
    closureGood=max(s.continuity_residual)<=.13&&max(s.opening_flow_residual)<=.17&& ...
        max(s.pressure_torque_residual)<=.13&&max(s.hydraulic_power_residual)<=.12&& ...
        max(s.mechanical_residual)<=.17&&s.state_rate_residual<=.05&& ...
        max([rows.pump_flow_residual])<=.05&&s.hydraulic_coefficients_physical&& ...
        s.pressure_torque_positive&&all(s.mechanical_branch_present);
    s.deadband_compensation_credit=s.opening_representation=="effective_opening"&& ...
        s.deadband_effect_strength<=1e-3&&s.deadband_pair_performance_good&&closureGood;
    s.valid=s.deadband_valid&&all(isfinite([s.continuity_residual s.continuity_signs(:)' ...
        s.opening_flow_residual s.opening_flow_coefficients s.opening_head_exponent ...
        s.pressure_torque_residual s.torque_sign s.hydraulic_power_residual ...
        s.mechanical_residual s.zero_valve_flow_ratio s.leak_passivity_by_branch ...
        s.leak_passivity_violation s.pressure_activity_by_axis s.flow_activity_by_axis ...
        s.torque_activity_by_axis s.motion_activity_by_axis s.state_rate_residual ...
        s.leak_monotonic_violation s.deadband_effect_strength ...
        s.deadband_opening_difference s.deadband_flow_difference]));
end
if nargout==1,varargout{1}=s;end
end

function [valid,effect,openingDiff,flowDiff,performanceGood]= ...
    deadband_pair_variable_timebase(runs,rows)
valid=false;effect=NaN;openingDiff=NaN;flowDiff=NaN;performanceGood=false;
names=string({runs.scenario});iLo=find(names=="deadband_probe_low",1);
iHi=find(names=="deadband_probe_high",1);
if isempty(iLo)||isempty(iHi),return;end
[tL,fL,ok1]=xp9_series(runs(iLo),'hydraulic_flow',10);
[tH,fH,ok2]=xp9_series(runs(iHi),'hydraulic_flow',10);
[t2,aL,ok3]=xp9_series(runs(iLo),'actuation',6);
[t3,aH,ok4]=xp9_series(runs(iHi),'actuation',6);
if ~(ok1&&ok2&&ok3&&ok4&&isequal(tL,t2)&&isequal(tH,t3)),return;end
event=min(double(runs(iLo).inputs.leak_event_time), ...
    double(runs(iHi).inputs.leak_event_time));
[~,low,high,aligned]=formal90_align_pair_timebase( ...
    tL,[fL(:,1:3),aL(:,1:3)],tH,[fH(:,1:3),aH(:,1:3)],.25,event-.1);
if ~aligned,return;end
capacity=double(runs(iLo).inputs.pump_flow_capacity);
flowDiff=rms(low(:,1:3)-high(:,1:3),'all')/max(capacity,1e-6);
openingDiff=rms(low(:,4:6)-high(:,4:6),'all');
performanceGood=rows(iLo).valid&&rows(iHi).valid&& ...
    max(rows(iLo).max_angle_error,rows(iHi).max_angle_error)<=1.2&& ...
    max(rows(iLo).tail_velocity,rows(iHi).tail_velocity)<=.75&& ...
    max(rows(iLo).pump_flow_residual,rows(iHi).pump_flow_residual)<=.05;
effect=max(openingDiff,flowDiff);
valid=all(isfinite([effect openingDiff flowDiff]));
end
